package com.company.tpm.employee; import org.springframework.stereotype.Component; import static com.company.tpm.employee.EmployeeDtos.*;
@Component public class EmployeeMapper{public EmployeeResponse toResponse(Employee e){return new EmployeeResponse(e.getId(),e.getStaffId(),e.getFullName(),e.getDepartment()==null?null:e.getDepartment().getName(),e.getSection()==null?null:e.getSection().getName(),e.getPosition()==null?null:e.getPosition().getName(),e.getShift(),e.getLocation(),e.getSupervisor()==null?null:e.getSupervisor().getFullName(),e.getStatus().name(),e.getVersion());}}
